import type { APIResponse, Page, Response } from '@playwright/test';
import { expect } from '@skyramp/skyramp';

export async function fillPetForm(page: Page, name: string, nickname: string, birthDate: string, typeName: string) {
    await page.locator("#name").fill(name);
    await page.locator("#nickname").fill(nickname);
    await page.locator("#birthDate").fill(birthDate);
    await page.getByLabel("Type").selectOption(typeName);
}

export async function submitPetForm(page: Page, buttonName: string, responseUrlPattern: string): Promise<Response> {
    const submitButton = page.getByRole("button", { name: buttonName });
    await expect(submitButton).toBeEnabled();
    const responsePromise = page.waitForResponse(responseUrlPattern);
    await submitButton.click();
    return await responsePromise;
}

export async function updatePetViaApi(
    page: Page,
    baseUrl: string,
    petId: number,
    name: string,
    nickname: string,
    birthDate: string,
    typeId: number,
    typeName: string,
    ownerId: number
): Promise<APIResponse> {
    return await page.request.put(`${baseUrl}/petclinic/api/pets/${petId}`, {
        data: {
            id: petId,
            name: name,
            nickname: nickname,
            birthDate: birthDate,
            type: { id: typeId, name: typeName },
            ownerId: ownerId,
            visits: []
        }
    });
}
